import styled from '@emotion/styled';

import {
  POS_BLEED_LINE_MARGIN_PX,
  POS_CHART_CANVAS_HEIGHT_PX,
} from './constants';

const POS_CHART_BLEED_LINE_COLOR = 'rgba(201, 209, 214, 1)';

export const StyledHeaderWrapper = styled.div`
  padding: 16px;
  border-bottom: 1px solid rgba(20, 20, 20, 0.16);
`;
export const StyledContainer = styled.div`
  padding: 0 24px 24px 24px;
`;

export const StyledPosChartBleedShell = styled.div<{ $height: number }>`
  position: relative;
  width: 100%;
  height: ${(p) => p.$height}px;
`;

export const StyledPosChartBleedLine = styled.div<{ $top: number }>`
  position: absolute;
  left: 0;
  right: 0;
  top: ${(p) => p.$top}px;
  height: 1px;
  background-color: ${POS_CHART_BLEED_LINE_COLOR};
  pointer-events: none;
  z-index: 2;
`;

export const StyledPosChartBleedLineX = styled.div<{ $top: number }>`
  position: absolute;
  left: ${POS_BLEED_LINE_MARGIN_PX}px;
  right: ${POS_BLEED_LINE_MARGIN_PX}px;
  top: ${(p) => p.$top}px;
  height: 1px;
  background-color: ${POS_CHART_BLEED_LINE_COLOR};
  pointer-events: none;
  z-index: 2;
`;

export const StyledChartPlotWrapper = styled.div`
  position: relative;
  z-index: 1;
  box-sizing: border-box;
  height: 100%;
  width: 100%;
`;

export const StyledChartCanvasWrapper = styled.div`
  height: 100%;
  min-height: ${POS_CHART_CANVAS_HEIGHT_PX}px;
  width: 100%;
`;

export const StyledComparisonLineWrapper = styled.div`
  padding: 0 16px 16px 16px;
`;

export const StyledLoadingContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
`;

export const StyledNoDataContainer = styled.div<{ $minHeight: number }>`
  width: 100%;
  height: ${(p) => p.$minHeight}px;
  display: flex;
  justify-content: center;
  align-items: center;
`;
